// Map + elevation viewer for the tracks in gpx/tracks.js (generated by gpx/make_gpx.py).
// Usage: <div class="gpxview" data-groups="huemul,planb"></div>, after Leaflet and tracks.js.
// The first group is what "All" shows; the other groups get their own buttons only.
(function(){
  var COLORS = ['#D97757','#4A7FB5','#2F8E83','#7A6CA8','#788C5D'];
  var L_ = function(es, en){ return '<span lang="es">'+es+'</span><span lang="en">'+en+'</span>'; };

  function cum(pts){
    var d = [0];
    for (var i = 1; i < pts.length; i++){
      d.push(d[i-1] + L.latLng(pts[i-1][0], pts[i-1][1]).distanceTo(L.latLng(pts[i][0], pts[i][1])));
    }
    return d;
  }

  function profile(el, pts, onHover){
    var d = cum(pts), W = 1000, H = 150, P = 28;
    var eles = pts.map(function(p){ return p[2]; });
    var lo = Math.min.apply(null, eles), hi = Math.max.apply(null, eles), span = Math.max(hi - lo, 50);
    var x = function(v){ return P + v / d[d.length-1] * (W - P - 8); };
    var y = function(v){ return H - 18 - (v - lo) / span * (H - 34); };
    var line = pts.map(function(p, i){ return (i ? 'L' : 'M') + x(d[i]).toFixed(1) + ' ' + y(p[2]).toFixed(1); }).join('');
    var km = d[d.length-1] / 1000, ticks = '';
    for (var k = 0; k <= km; k += km > 30 ? 10 : km > 12 ? 5 : 2){
      ticks += '<text x="'+x(k*1000)+'" y="'+(H-3)+'" text-anchor="middle">'+k+' km</text>';
    }
    el.innerHTML = '<svg viewBox="0 0 '+W+' '+H+'" preserveAspectRatio="none" role="img" aria-label="Elevation profile">'
      + '<path d="'+line+' L'+x(d[d.length-1])+' '+(H-18)+' L'+P+' '+(H-18)+'Z" class="gv-area"/>'
      + '<path d="'+line+'" class="gv-line"/>'
      + '<text x="2" y="'+(y(hi)+4)+'">'+Math.round(hi)+'</text><text x="2" y="'+(y(lo)+4)+'">'+Math.round(lo)+'</text>'
      + ticks + '<line class="gv-cursor" x1="-10" x2="-10" y1="0" y2="'+(H-18)+'"/></svg>'
      + '<div class="gv-readout"></div>';
    var svg = el.querySelector('svg'), cur = el.querySelector('.gv-cursor'), out = el.querySelector('.gv-readout');
    function move(ev){
      var r = svg.getBoundingClientRect();
      var cx = ((ev.touches ? ev.touches[0].clientX : ev.clientX) - r.left) / r.width * W;
      var target = (cx - P) / (W - P - 8) * d[d.length-1], i = 0;
      while (i < d.length - 1 && d[i] < target) i++;
      cur.setAttribute('x1', x(d[i])); cur.setAttribute('x2', x(d[i]));
      out.textContent = (d[i]/1000).toFixed(1) + ' km · ' + Math.round(pts[i][2]) + ' m';
      onHover(pts[i]);
    }
    svg.addEventListener('mousemove', move);
    svg.addEventListener('touchmove', move, {passive:true});
  }

  function build(el){
    var groups = el.dataset.groups.split(',');
    var days = [];
    groups.forEach(function(g){ (TRACKS[g] || []).forEach(function(t){ days.push(t); }); });
    var main = TRACKS[groups[0]] || [];

    el.innerHTML = '<div class="gv-map"></div><div class="gv-btns"></div><div class="gv-stats"></div>'
      + '<div class="gv-prof"></div><div class="gv-dl"></div>';
    var map = L.map(el.querySelector('.gv-map'), {scrollWheelZoom:false});
    var topo = L.tileLayer('https://{s}.tile.opentopomap.org/{z}/{x}/{y}.png', {maxZoom:17,
      attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>, SRTM · <a href="https://opentopomap.org">OpenTopoMap</a> (CC-BY-SA)'});
    var osm = L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png', {maxZoom:19,
      attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>'});
    topo.addTo(map);
    L.control.layers({'Topo': topo, 'OSM': osm}).addTo(map);

    var layers = days.map(function(t, i){
      var color = COLORS[main.indexOf(t) >= 0 ? main.indexOf(t) % COLORS.length : 0];
      var lg = L.featureGroup([L.polyline(t.pts.map(function(p){ return [p[0], p[1]]; }), {color:color, weight:4, opacity:.9})]);
      t.wpts.forEach(function(w){
        L.circleMarker([w[0], w[1]], {radius:5, color:'#141413', weight:1.5, fillColor:'#FFF', fillOpacity:1})
          .bindTooltip(w[2]).addTo(lg);
      });
      return lg;
    });
    var hover = L.circleMarker([0,0], {radius:7, color:'#141413', weight:2, fillColor:'#D97757', fillOpacity:1});

    var btns = el.querySelector('.gv-btns');
    function show(sel){
      layers.forEach(function(l){ map.removeLayer(l); });
      map.removeLayer(hover);
      var on = sel === 'all' ? main.map(function(t){ return days.indexOf(t); }) : [sel];
      on.forEach(function(i){ layers[i].addTo(map); });
      map.fitBounds(L.featureGroup(on.map(function(i){ return layers[i]; })).getBounds(), {padding:[18,18]});
      [].forEach.call(btns.children, function(b){ b.classList.toggle('on', b.dataset.k == String(sel)); });

      var picked = on.map(function(i){ return days[i]; });
      var sum = function(f){ return picked.reduce(function(a, t){ return a + t[f]; }, 0); };
      el.querySelector('.gv-stats').innerHTML = '<b>' + sum('km').toFixed(1) + ' km</b> · +' + sum('up') + ' m / −' + sum('down') + ' m'
        + ' · ' + L_('máx.', 'max') + ' ' + Math.max.apply(null, picked.map(function(t){ return t.max; })) + ' m'
        + (sel === 'all' ? '' : ' · <span class="gv-title">' + days[sel].title + '</span>');
      var pts = [].concat.apply([], picked.map(function(t){ return t.pts; }));
      profile(el.querySelector('.gv-prof'), pts, function(p){ hover.setLatLng([p[0], p[1]]).addTo(map); });
    }
    var mk = function(k, label){
      var b = document.createElement('button'); b.className = 'btn'; b.dataset.k = k; b.innerHTML = label;
      b.onclick = function(){ show(k === 'all' ? 'all' : +k); }; btns.appendChild(b);
    };
    if (main.length > 1) mk('all', L_('Todo', 'All days'));
    days.forEach(function(t, i){ mk(String(i), t.title.split(' · ')[0]); });

    var dl = main.length > 1 && !el.dataset.noAll ? ['<a href="gpx/' + groups[0] + '_all-days.gpx" download>' + L_('todos los días', 'all days') + '</a>'] : [];
    // ponytail: tracks.html entries carry url (Wikiloc page) or file:null (no public copy)
    days.forEach(function(t){
      var n = t.title.split(' · ')[0];
      if (t.url) dl.push('<a href="' + t.url + '" target="_blank" rel="noopener">' + n + ' ↗</a>');
      else if (t.file) dl.push('<a href="gpx/' + t.file + '" download>' + n + '</a>');
    });
    el.querySelector('.gv-dl').innerHTML = '⬇️ GPX: ' + dl.join(' · ');
    show(main.length > 1 ? 'all' : 0);
  }

  document.addEventListener('DOMContentLoaded', function(){
    [].forEach.call(document.querySelectorAll('.gpxview'), build);
  });
})();
